import os
from pathlib import Path

import pytest

NOTES_DIR = "notes"


def resolve_note(name: str) -> Path | None:
    """Resolve `name` to a path strictly inside NOTES_DIR (relative to the
    current working directory), or return None.

    Returns None for any name that would land outside NOTES_DIR after
    normalisation and symlink resolution: absolute paths, `..` escapes,
    symlinks pointing outside, names containing NUL bytes, and the empty
    name or any name resolving to NOTES_DIR itself. Never raises.
    The target need not exist.
    """
    if not name or "\x00" in name:
        return None
    try:
        if os.path.isabs(name) or Path(name).anchor or Path(name).drive:
            return None
        base = Path(NOTES_DIR).resolve()
        candidate = (base / name).resolve()
        if candidate == base or not candidate.is_relative_to(base):
            return None
        return candidate
    except (OSError, ValueError, RuntimeError):
        return None


def read_note(name: str) -> str:
    """Return the text of the file `name` inside NOTES_DIR.

    Returns "" if the file is missing, is not a regular file, is unreadable,
    or if `name` would escape NOTES_DIR. Never raises and never reads
    anything outside NOTES_DIR.
    """
    path = resolve_note(name)
    if path is None:
        return ""
    try:
        if not path.is_file():
            return ""
        with open(path, encoding="utf-8", errors="replace") as f:
            return f.read()
    except (OSError, ValueError):
        return ""


def count_readable(names: list[str]) -> int:
    """Count the entries of `names` that are regular files inside NOTES_DIR
    which can be opened and read.

    Each entry is counted independently, so duplicates count each time.
    Names may be hostile: any name that would reach outside NOTES_DIR
    (absolute, `..`, symlink escape, NUL byte, ...) is not counted and
    never causes an exception. An empty but readable file is counted.
    """
    total = 0
    for name in names:
        path = resolve_note(name)
        if path is None:
            continue
        try:
            if not path.is_file():
                continue
            with open(path, encoding="utf-8", errors="replace") as f:
                f.read()
        except (OSError, ValueError):
            continue
        total += 1
    return total


@pytest.fixture
def workdir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / NOTES_DIR
    notes.mkdir()
    (notes / "a.txt").write_text("alpha")
    (notes / "b.txt").write_text("beta")
    (notes / "empty.txt").write_text("")
    (notes / "sub").mkdir()
    (notes / "sub" / "c.txt").write_text("gamma")
    (tmp_path / "secret.txt").write_text("top secret")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_counts_existing_files(workdir: Path) -> None:
    assert count_readable(["a.txt", "b.txt"]) == 2


def test_empty_list(workdir: Path) -> None:
    assert count_readable([]) == 0


def test_missing_not_counted(workdir: Path) -> None:
    assert count_readable(["a.txt", "nope.txt"]) == 1


def test_empty_file_is_counted(workdir: Path) -> None:
    assert count_readable(["empty.txt"]) == 1


def test_duplicates_counted_each_time(workdir: Path) -> None:
    assert count_readable(["a.txt", "a.txt", "b.txt"]) == 3


def test_subdirectory_file(workdir: Path) -> None:
    assert count_readable(["sub/c.txt"]) == 1


def test_directory_not_counted(workdir: Path) -> None:
    assert count_readable(["sub"]) == 0


def test_empty_and_dot_names(workdir: Path) -> None:
    assert count_readable(["", ".", "./"]) == 0


def test_inner_dotdot_staying_inside(workdir: Path) -> None:
    assert count_readable(["sub/../a.txt"]) == 1


def test_parent_traversal_rejected(workdir: Path) -> None:
    assert count_readable(["../secret.txt"]) == 0
    assert count_readable(["sub/../../secret.txt"]) == 0
    assert count_readable(["../notes/../secret.txt"]) == 0
    assert count_readable([".."]) == 0


def test_absolute_path_rejected(workdir: Path) -> None:
    secret = str(workdir / "secret.txt")
    assert count_readable([secret]) == 0
    inside = str(workdir / NOTES_DIR / "a.txt")
    assert count_readable([inside]) == 0


def test_nul_byte_rejected(workdir: Path) -> None:
    assert count_readable(["a.txt\x00", "a.txt\x00../secret.txt"]) == 0


def test_symlink_escape_rejected(workdir: Path) -> None:
    link = workdir / NOTES_DIR / "link.txt"
    try:
        link.symlink_to(workdir / "secret.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert count_readable(["link.txt"]) == 0
    assert read_note("link.txt") == ""


def test_symlink_dir_escape_rejected(workdir: Path) -> None:
    link = workdir / NOTES_DIR / "outside"
    try:
        link.symlink_to(workdir, target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert count_readable(["outside/secret.txt"]) == 0


def test_symlink_inside_notes_allowed(workdir: Path) -> None:
    link = workdir / NOTES_DIR / "alias.txt"
    try:
        link.symlink_to(workdir / NOTES_DIR / "a.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert count_readable(["alias.txt"]) == 1


@pytest.mark.skipif(
    not hasattr(os, "geteuid") or os.geteuid() == 0,
    reason="permission bits not enforced",
)
def test_unreadable_file_not_counted(workdir: Path) -> None:
    locked = workdir / NOTES_DIR / "locked.txt"
    locked.write_text("x")
    locked.chmod(0)
    try:
        assert count_readable(["locked.txt", "a.txt"]) == 1
        assert read_note("locked.txt") == ""
    finally:
        locked.chmod(0o600)


def test_read_note_contents(workdir: Path) -> None:
    assert read_note("a.txt") == "alpha"
    assert read_note("sub/c.txt") == "gamma"


def test_read_note_failures_give_empty(workdir: Path) -> None:
    assert read_note("missing.txt") == ""
    assert read_note("sub") == ""
    assert read_note("../secret.txt") == ""
    assert read_note(str(workdir / "secret.txt")) == ""
    assert read_note("a.txt\x00") == ""


def test_resolve_note(workdir: Path) -> None:
    p = resolve_note("a.txt")
    assert p is not None
    assert p.resolve() == (workdir / NOTES_DIR / "a.txt").resolve()
    assert resolve_note("../secret.txt") is None
    assert resolve_note("") is None
    assert resolve_note("a\x00b") is None
    assert resolve_note(str(workdir / "secret.txt")) is None


def test_missing_notes_dir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.chdir(tmp_path)
    assert count_readable(["a.txt", "../x"]) == 0
